@verbatim
<template x-if="$store.app.route.page === 'finance.reports'">
  <div x-data="reportsPage()">
    <div class="mb-4 flex flex-wrap items-center gap-3"><h1 class="text-2xl font-bold" x-text="$store.app.t('reports')"></h1>
      <div class="flex gap-1"><template x-for="tb in ['sales','occupancy','profit','cash']" :key="tb"><button class="btn btn-secondary btn-sm capitalize" :class="tab === tb ? 'ring-2 ring-emerald-500' : ''" @click="setTab(tb)" x-text="tb"></button></template></div>
      <input type="date" class="input w-auto" x-model="from" @change="run()"><input type="date" class="input w-auto" x-model="to" @change="run()">
      <select class="input w-auto" x-show="tab === 'sales'" x-model="group" @change="run()"><option value="day">By day</option><option value="item">By item</option><option value="method">By payment method</option><option value="user">By cashier</option></select>
      <button class="btn btn-secondary" x-show="['sales','occupancy'].includes(tab)" @click="csv()" x-text="$store.app.t('export')"></button></div>
    <p x-show="loading" class="text-slate-500" x-text="$store.app.t('loading')"></p>
    <template x-if="tab === 'sales'"><div class="space-y-1"><template x-for="r in rows" :key="r.key"><div class="flex items-center gap-3 text-sm"><span class="w-40 truncate" x-text="r.key"></span><div class="h-5 flex-1 rounded bg-slate-200"><div class="h-5 rounded bg-emerald-500" :style="'width:' + (100 * Number(r.amount) / max()) + '%'"></div></div><span class="w-32 text-right" x-text="money(r.amount)"></span></div></template><p x-show="!rows.length && !loading" class="text-slate-500" x-text="$store.app.t('no_data')"></p></div></template>
    <template x-if="tab === 'occupancy'"><div class="space-y-3">
      <div class="grid gap-3 sm:grid-cols-4" x-show="summary"><div class="card"><p class="text-xs text-slate-500">Occupancy</p><p class="text-xl font-bold" x-text="summary?.occupancy_pct + '%'"></p></div><div class="card"><p class="text-xs text-slate-500">ADR</p><p class="text-xl font-bold" x-text="money(summary?.adr)"></p></div><div class="card"><p class="text-xs text-slate-500">RevPAR</p><p class="text-xl font-bold" x-text="money(summary?.revpar)"></p></div><div class="card"><p class="text-xs text-slate-500">Room revenue</p><p class="text-xl font-bold" x-text="money(summary?.room_revenue)"></p></div></div>
      <div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50"><tr><th class="th" x-text="$store.app.t('date')"></th><th class="th">Sold</th><th class="th">Occ %</th><th class="th">Revenue</th><th class="th">ADR</th><th class="th">RevPAR</th></tr></thead>
        <tbody class="divide-y divide-slate-100"><template x-for="r in rows" :key="r.date"><tr><td class="td" x-text="r.date"></td><td class="td" x-text="r.rooms_sold + '/' + r.rooms_total"></td><td class="td" x-text="r.occupancy_pct"></td><td class="td" x-text="money(r.room_revenue)"></td><td class="td" x-text="money(r.adr)"></td><td class="td" x-text="money(r.revpar)"></td></tr></template></tbody></table></div></div></template>
    <template x-if="tab === 'profit' && profit"><div class="grid gap-3 sm:grid-cols-3"><div class="card"><p class="text-xs text-slate-500">Collected</p><p class="text-2xl font-bold" x-text="money(profit.revenue_collected)"></p></div><div class="card"><p class="text-xs text-slate-500">Expenses</p><p class="text-2xl font-bold" x-text="money(profit.expenses)"></p></div><div class="card"><p class="text-xs text-slate-500">Net</p><p class="text-2xl font-bold" :class="profit.net < 0 ? 'text-red-600' : 'text-emerald-700'" x-text="money(profit.net)"></p></div>
      <div class="card sm:col-span-3"><h3 class="mb-2 font-semibold">Expenses by category</h3><template x-for="[k, v] in Object.entries(profit.expenses_by_category)" :key="k"><div class="flex justify-between text-sm"><span x-text="k"></span><span x-text="money(v)"></span></div></template></div></div></template>
    <template x-if="tab === 'cash'"><div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50"><tr><th class="th">Opened</th><th class="th">Float</th><th class="th">Expected</th><th class="th">Counted</th><th class="th">Variance</th></tr></thead>
      <tbody class="divide-y divide-slate-100"><template x-for="s in rows" :key="s.id"><tr><td class="td" x-text="(s.opened_at || '').slice(0,16).replace('T',' ')"></td><td class="td" x-text="money(s.opening_float)"></td><td class="td" x-text="money(s.expected_cash)"></td><td class="td" x-text="s.counted_cash === null ? '' : money(s.counted_cash)"></td><td class="td" :class="s.variance < 0 ? 'text-red-600' : ''" x-text="s.variance === null ? '' : money(s.variance)"></td></tr></template></tbody></table></div></template>
  </div>
</template>
@endverbatim
